static inline int TIXML_SNPRINTF( char* buffer, size_t size, const char* format, ... )
{
	va_list va;
	va_start( va, format );
	const int result = vsnprintf_s( buffer, size, _TRUNCATE, format, va );
	va_end( va );
	return result;
}

